{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MAPLEMONK.FYTIKA_DB_PRODUCT_MARKETING_CONSOLIDATED AS WITH sales AS ( SELECT order_date, CAST(product_id AS STRING) AS product_id, SUM(IFNULL(selling_price,0)) AS sales FROM `maplemonk.maplemonk_analytics_sales_consolidated` GROUP BY 1,2 ), shopify AS ( SELECT CAST(PRODUCT_ID AS STRING) AS PRODUCT_ID, CAST(VARIANT_ID AS STRING) AS VARIANT_ID, CAST(SKU AS STRING) AS SKU, CAST(Product_Category AS STRING) AS Product_Category FROM maplemonk.maplemonk_analytics_SHOPIFY_FACT_ITEMS QUALIFY ROW_NUMBER() OVER (PARTITION BY SKU ORDER BY Product_Category) = 1 ), sku_map AS ( SELECT DISTINCT CAST(channel_product_id AS STRING) AS channel_product_id, CAST(sku_code AS STRING) AS sku_code FROM `maplemonk-analytics.maplemonk.unicommerce_fytika_get_product_listing` WHERE sku_code IS NOT NULL ), facebook AS ( SELECT CAST(fc.Adset_Name AS STRING) AS ADSET_NAME, CAST(fc.Adset_ID AS STRING) AS ADSET_ID, CAST(fc.ad_id AS STRING) AS AD_ID, CAST(fc.ad_name AS STRING) AS AD_NAME, CAST(fc.Account_Name AS STRING) AS ACCOUNT_NAME, CAST(fc.Account_ID AS STRING) AS ACCOUNT_ID, CAST(fc.Campaign_Name AS STRING) AS CAMPAIGN_NAME, CAST(fc.Campaign_ID AS STRING) AS CAMPAIGN_ID, CAST(fc.product_id AS STRING) AS PRODUCT_ID, CAST(sc.VARIANT_ID AS STRING) AS VARIANT_ID, DATE(fc.Date) AS DATE, CAST(NULL AS STRING) AS AD_TYPE, CAST(NULL AS STRING) AS AD_STRENGTH, CAST(NULL AS STRING) AS AD_NETWORK_TYPE, CAST(NULL AS STRING) AS AD_FINAL_URL, FORMAT_DATE(\'%A\', DATE(fc.Date)) AS DAY_OF_WEEK, EXTRACT(YEAR FROM DATE(fc.Date)) AS YEAR, EXTRACT(MONTH FROM DATE(fc.Date)) AS MONTH, CAST(fc.Channel AS STRING) AS CHANNEL, CAST(fc.Account AS STRING) AS ACCOUNT, SUM(CAST(fc.Clicks AS FLOAT64)) AS CLICKS, SUM(CAST(fc.Spend AS FLOAT64)) AS SPEND, SUM(CAST(fc.Impressions AS FLOAT64)) AS IMPRESSIONS, SUM(CAST(fc.Conversions AS FLOAT64)) AS CONVERSIONS, SUM(CAST(fc.Conversion_Value AS FLOAT64)) AS CONVERSION_VALUE, CAST(sc.Product_Category AS STRING) AS PRODUCT_CATEGORY, SUM(IFNULL(sl.sales,0)) AS SALES, LOWER(TRIM(COALESCE(sc.SKU, sm.sku_code, CAST(fc.product_id AS STRING)))) AS SKU FROM maplemonk.fytika_db_Product_FACEBOOK_CONSOLIDATED fc LEFT JOIN shopify sc ON CAST(fc.product_id AS STRING) IN (sc.PRODUCT_ID, sc.VARIANT_ID) LEFT JOIN sku_map sm ON CAST(fc.product_id AS STRING) = sm.channel_product_id LEFT JOIN sales sl ON CAST(fc.product_id AS STRING) = sl.product_id AND DATE(fc.Date) = sl.order_date GROUP BY ALL ), google AS ( SELECT CAST(gc.ADSET_NAME AS STRING), CAST(gc.ADSET_ID AS STRING), CAST(gc.AD_ID AS STRING), CAST(gc.AD_NAME AS STRING), CAST(gc.ACCOUNT_NAME AS STRING), CAST(gc.ACCOUNT_ID AS STRING), CAST(gc.CAMPAIGN_NAME AS STRING), CAST(gc.CAMPAIGN_ID AS STRING), CAST(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(2)] AS STRING), CAST(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(3)] AS STRING), DATE(gc.Date), CAST(gc.AD_TYPE AS STRING), CAST(gc.AD_STRENGTH AS STRING), CAST(gc.AD_NETWORK_TYPE AS STRING), CAST(gc.AD_FINAL_URL AS STRING), CAST(gc.DAY_OF_WEEK AS STRING), CAST(gc.YEAR AS INT64), CAST(gc.MONTH AS INT64), CAST(gc.Channel AS STRING), CAST(gc.Account AS STRING), SUM(CAST(gc.clicks AS FLOAT64)), SUM(CAST(gc.spend AS FLOAT64)), SUM(CAST(gc.Impressions AS FLOAT64)), SUM(CAST(gc.Conversions AS FLOAT64)), SUM(CAST(gc.Conversion_Value AS FLOAT64)), CAST(sc.Product_Category AS STRING), SUM(IFNULL(sl.sales,0)), LOWER(TRIM(COALESCE( sc.SKU, sm.sku_code, CAST(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(2)] AS STRING) ))) AS SKU FROM maplemonk.Fytika_db_Product_GOOGLEADS_CONSOLIDATED gc LEFT JOIN shopify sc ON CAST(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(2)] AS STRING) IN (sc.PRODUCT_ID, sc.VARIANT_ID) LEFT JOIN sku_map sm ON CAST(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(2)] AS STRING) = sm.channel_product_id LEFT JOIN sales sl ON CAST(SPLIT(gc.segments_product_item_id, \'_\')[SAFE_OFFSET(2)] AS STRING) = sl.product_id AND DATE(gc.Date) = sl.order_date GROUP BY ALL ), amazon AS ( SELECT CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(a.AD_ID AS STRING), CAST(a.NAME AS STRING), CAST(a.NAME AS STRING), CAST(a.PROFILEID AS STRING), CAST(a.CAMPAIGNNAME AS STRING), CAST(a.CAMPAIGN_ID AS STRING), CAST(a.ASIN AS STRING), CAST(sc.VARIANT_ID AS STRING), a.DATE, CAST(a.AD_TYPE_1 AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING), FORMAT_DATE(\'%A\', a.DATE), EXTRACT(YEAR FROM a.DATE), EXTRACT(MONTH FROM a.DATE), CAST(\'Amazon\' AS STRING), CAST(a.NAME AS STRING), a.clicks, a.spend, a.impressions, a.conversions, a.conversion_value, CAST(sc.Product_Category AS STRING), IFNULL(sl.sales,0), LOWER(TRIM(COALESCE(sc.SKU, sm.sku_code, a.sku_code))) AS SKU FROM ( SELECT AD_ID, NAME, PROFILEID, CAMPAIGNNAME, CAMPAIGN_ID, ASIN, sku_code, DATE(Date) AS DATE, AD_TYPE_1, SUM(clicks) clicks, SUM(spend) spend, SUM(Impressions) impressions, SUM(ATTRIBUTED_CONVERSIONS_14D) conversions, SUM(ATTRIBUTED_SALES_14D) conversion_value FROM `maplemonk-analytics.maplemonk.fytika_AMAZON_ADS_HOURLY_DATA_CONSOLIDATED` GROUP BY 1,2,3,4,5,6,7,8,9 ) a LEFT JOIN shopify sc ON CAST(a.ASIN AS STRING) IN (sc.PRODUCT_ID, sc.VARIANT_ID) LEFT JOIN sku_map sm ON CAST(a.ASIN AS STRING) = sm.channel_product_id LEFT JOIN sales sl ON CAST(a.ASIN AS STRING) = sl.product_id AND a.DATE = sl.order_date ), flipkart AS ( SELECT CAST(fk.Adset_Name AS STRING), CAST(fk.Adset_ID AS STRING), CAST(fk.ad_id AS STRING), CAST(fk.ad_name AS STRING), CAST(fk.Account_Name AS STRING), CAST(fk.Account_ID AS STRING), CAST(fk.Campaign_Name AS STRING), CAST(fk.Campaign_ID AS STRING), CAST(fk.product_id AS STRING), CAST(fk.VARIANT_ID AS STRING), fk.DATE, CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING), CAST(NULL AS STRING), FORMAT_DATE(\'%A\', fk.Date), EXTRACT(YEAR FROM fk.Date), EXTRACT(MONTH FROM fk.Date), CAST(fk.Channel AS STRING), CAST(fk.Account AS STRING), SUM(CAST(fk.Clicks AS FLOAT64)), SUM(CAST(fk.Spend AS FLOAT64)), SUM(CAST(fk.Impressions AS FLOAT64)), SUM(CAST(fk.Conversions AS FLOAT64)), SUM(CAST(fk.Conversion_Value AS FLOAT64)), CAST(fk.Product_Category AS STRING), SUM(CAST(fk.SALES AS FLOAT64)), LOWER(TRIM(COALESCE(sc.SKU, sm.sku_code, CAST(fk.product_id AS STRING)))) AS SKU FROM maplemonk.Fytika_db_Product_Flipkart_FSN fk LEFT JOIN shopify sc ON CAST(fk.product_id AS STRING) IN (sc.PRODUCT_ID, sc.VARIANT_ID) LEFT JOIN sku_map sm ON CAST(fk.product_id AS STRING) = sm.channel_product_id GROUP BY ALL ), marketing_consolidated_intermediate AS ( SELECT * FROM facebook UNION ALL SELECT * FROM google UNION ALL SELECT * FROM amazon UNION ALL SELECT * FROM flipkart ) SELECT *, SUM(SPEND) OVER (PARTITION BY DATE, CHANNEL) AS TOTAL_CHANNEL_SPEND, SUM(SALES) OVER (PARTITION BY DATE, CHANNEL) AS TOTAL_CHANNEL_SALES, CASE WHEN SUM(SALES) OVER (PARTITION BY DATE, CHANNEL) = 0 THEN 0 ELSE SUM(SPEND) OVER (PARTITION BY DATE, CHANNEL) * (SALES / SUM(SALES) OVER (PARTITION BY DATE, CHANNEL)) END AS BRAND_SPEND FROM marketing_consolidated_intermediate;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            